    private fun outboxFile(dir: File) = AtomicFileValue(File(dir, "outbox.json"), ListSerializer(String.serializer()), json)

    @Test
    fun `REQ-PERSIST-001 write then read returns the value and leaves no temp file`() {
        val dir = File(folder.root, "chatgen")
        val value = outboxFile(dir)
        assertNull(value.read())
        value.write(listOf("a", "b"))
        value.write(listOf("b"))
        assertEquals(listOf("b"), outboxFile(dir).read())
        assertFalse(File(dir, "outbox.json.tmp").exists())
    }

    @Test
    fun `REQ-PERSIST-001 a crash while writing the temp file leaves the old value`() {
        val dir = File(folder.root, "chatgen")
        val value = outboxFile(dir)
        value.write(listOf("old"))
        // Simulate a crash mid-write: a partial temp file that was never moved into place.
        File(dir, "outbox.json.tmp").writeText("[\"new\", \"par")
        assertEquals(listOf("old"), outboxFile(dir).read())
        // The next write still succeeds and replaces the value.
        value.write(listOf("new"))
        assertEquals(listOf("new"), outboxFile(dir).read())
    }

    @Test
    fun `delete removes the value`() {
        val dir = File(folder.root, "chatgen")
        val cursor = AtomicFileValue(File(dir, "cursor.json"), Long.serializer(), json)
